"""
Glossary. One entry per term used by the curriculum, the tours or the tool's own labels.

T(id, term, short, aka, see, concept, match)
  id       stable slug, used in [[id]] links and in URLs
  term     display form
  short    one or two plain-text sentences (no markup); must stand alone as a tooltip
  aka      other names and spellings (searchable)
  see      related term ids
  concept  id of the curriculum concept that explains it in context
  match    exact strings that the tool underlines in its own views when Learn mode is on
           (case-sensitive, whole words). Only distinctive spellings are listed, so that
           ordinary words such as "section" are not underlined everywhere.
"""

from typing import Any, Dict, List, Sequence


def T(id: str, term: str, short: str, aka: Sequence[str] = (), see: Sequence[str] = (), concept: str = "",
      match: Sequence[str] = ()) -> Dict[str, Any]:
    return {"id": id, "term": term, "short": short, "aka": list(aka), "see": list(see), "concept": concept,
            "match": list(match)}


