    T("export-directory", "export directory", "The PE table of a DLL's exported functions (data directory 0): addresses by ordinal, a sorted name table, and the mapping between them.", aka=["IMAGE_EXPORT_DIRECTORY", "EAT", "export address table"], see=["export", "ordinal", "forwarder"], concept="pe-imports", match=["DATA_DIR_EXPORT_TABLE"]),
    T("ordinal", "ordinal", "A number that identifies a symbol or a library instead of a name. In PE, an export's index in the export address table plus the directory's Base; in Mach-O, the position of a library, counted from 1, among the commands that load dylibs.", aka=["library ordinal", "export ordinal"], see=["export-directory", "two-level-namespace"], concept="pe-imports", match=["ordinal", "Library ordinal"]),
    T("forwarder", "forwarder", "A PE export that does not point at code but names a function in another DLL, to which the loader redirects importers.", aka=["forwarded export"], see=["export-directory"], concept="pe-imports"),
    T("name-mangling", "name mangling", "Encoding a function's namespace and parameter types into its symbol name so that the linker can tell overloads apart.", aka=["mangled name", "decorated name", "name decoration", "_Z"], see=["demangling", "abi"], concept="name-mangling"),
    T("demangling", "demangling", "Converting a mangled symbol name back into a readable declaration.", aka=["demangle", "c++filt", "undname"], see=["name-mangling"], concept="name-mangling", match=["Demangle"]),
    T("two-level-namespace", "two-level namespace", "The Mach-O rule that each imported symbol is bound to one named library (by ordinal) rather than looked up in every loaded image. Marked by MH_TWOLEVEL.", aka=["MH_TWOLEVEL", "flat namespace"], see=["ordinal", "bind", "interposition"], concept="dyld-fixups", match=["MH_TWOLEVEL"]),
    T("interposition", "interposition", "Replacing a library's function by an earlier definition of the same name, as LD_PRELOAD does on ELF systems.", aka=["LD_PRELOAD", "DYLD_INSERT_LIBRARIES", "symbol preemption"], see=["two-level-namespace", "dynamic-linker"], concept="elf-dynamic"),
    T("indirect-symbol-table", "indirect symbol table", "A Mach-O array of symbol indices, one for each stub and each pointer slot, in section order. It is how a slot is tied to a name.", aka=["indirect symbols", "indirectsymoff"], see=["stub", "got", "dysymtab"], concept="got-plt", match=["Indirect symbols", "indirect symbol"]),
    T("function-starts", "function starts", "The Mach-O table (LC_FUNCTION_STARTS) of addresses where functions begin, stored as ULEB128 distances. Present even when symbols are stripped.", aka=["LC_FUNCTION_STARTS"], see=["strip", "leb128"], concept="stripping", match=["LC_FUNCTION_STARTS", "Function starts"]),
    T("data-in-code", "data in code", "The Mach-O table (LC_DATA_IN_CODE) of ranges inside the code section that hold data, such as jump tables.", aka=["LC_DATA_IN_CODE"], see=["disassembly"], concept="reading-disassembly", match=["LC_DATA_IN_CODE"]),

    # ---- relocations and binding
    T("relocation", "relocation", "A record asking the linker or loader to write an address at a given place once that address is known.", aka=["reloc", "Elf64_Rela", "relocation_info"], see=["rebase", "bind", "fixup", "addend"], concept="relocations"),
    T("addend", "addend", "A constant added to the symbol's address when a relocation is applied. Stored in the record (RELA) or at the place being relocated (REL).", aka=["r_addend", "RELA", "REL"], see=["relocation"], concept="relocations"),
    T("rebase", "rebase", "A load-time adjustment of a pointer that refers into its own image: the slide is added to it. ELF calls it a relative relocation; PE a base relocation.", aka=["relative relocation", "R_X86_64_RELATIVE", "R_AARCH64_RELATIVE", "DT_RELR"], see=["slide", "bind", "base-relocation"], concept="relocations", match=["rebase", "Rebase", "R_X86_64_RELATIVE", "R_AARCH64_RELATIVE"]),
    T("bind", "bind", "A load-time write of the address of an imported symbol into a pointer slot.", aka=["binding", "symbol binding", "GLOB_DAT", "JUMP_SLOT"], see=["rebase", "import", "lazy-binding"], concept="relocations", match=["bind", "Bind", "R_X86_64_GLOB_DAT", "R_X86_64_JUMP_SLOT"]),
    T("fixup", "fixup", "This tool's general word for a load-time relocation: a rebase or a bind.", see=["rebase", "bind", "chained-fixups"], concept="relocations", match=["fixup", "Fixup", "fixups", "Fixups"]),
    T("chained-fixups", "chained fixups", "The current Mach-O encoding of load-time fixups (LC_DYLD_CHAINED_FIXUPS): each pointer slot holds its target and the distance to the next slot, forming a chain per page that dyld walks.", aka=["LC_DYLD_CHAINED_FIXUPS", "fixup chains", "DYLD_CHAINED_PTR"], see=["fixup", "dyld-info", "rebase", "bind"], concept="dyld-fixups", match=["LC_DYLD_CHAINED_FIXUPS", "chained fixups", "Chained fixups"]),
    T("dyld-info", "dyld info", "The older Mach-O encoding of load-time fixups (LC_DYLD_INFO, LC_DYLD_INFO_ONLY): byte-code streams for rebases, binds, weak binds and lazy binds, and the export trie.", aka=["LC_DYLD_INFO_ONLY", "LC_DYLD_INFO", "bind opcodes", "rebase opcodes"], see=["chained-fixups", "leb128", "export-trie"], concept="dyld-fixups", match=["LC_DYLD_INFO_ONLY", "LC_DYLD_INFO"]),
    T("base-relocation", "base relocation", "An entry of the PE .reloc table: the location of a pointer that must be adjusted if the image is not loaded at ImageBase.", aka=[".reloc", "IMAGE_BASE_RELOCATION", "IMAGE_REL_BASED_DIR64", "IMAGE_REL_BASED_HIGHLOW"], see=["rebase", "image-base", "aslr"], concept="relocations", match=[".reloc", "DATA_DIR_BASE_RELOCATION_TABLE"]),

    # ---- dynamic linking
    T("dyld", "dyld", "The macOS dynamic linker, /usr/lib/dyld. Loaded by the kernel into every dynamically linked process.", aka=["LC_LOAD_DYLINKER", "dynamic link editor"], see=["dynamic-linker", "dyld-shared-cache", "chained-fixups"], concept="process-startup-macos", match=["LC_LOAD_DYLINKER"]),
    T("dyld-shared-cache", "dyld shared cache", "A pre-linked image of most system libraries, built by Apple and stored as one file or, on current systems, a set of files. It is mapped into every process; since macOS 11 the individual library files are no longer on disk.", aka=["shared cache", "dyld_shared_cache"], see=["dyld", "aslr"], concept="shared-libraries"),
    T("interpreter", "interpreter", "In ELF, the program named by PT_INTERP that the kernel loads and runs first: the dynamic linker.", aka=["PT_INTERP", ".interp", "program interpreter", "ld-linux"], see=["dynamic-linker", "program-header"], concept="process-startup-linux", match=["PT_INTERP", ".interp"]),
    T("install-name", "install name", "The path stored in a Mach-O dynamic library (LC_ID_DYLIB) that is copied into every image linked against it (LC_LOAD_DYLIB).", aka=["LC_LOAD_DYLIB", "LC_ID_DYLIB", "@rpath", "@executable_path", "@loader_path"], see=["rpath", "soname", "shared-library"], concept="shared-libraries", match=["LC_LOAD_DYLIB", "LC_ID_DYLIB", "LC_LOAD_WEAK_DYLIB", "LC_REEXPORT_DYLIB"]),
    T("soname", "SONAME", "The name an ELF shared library asks to be recorded under (DT_SONAME), such as libc.so.6. It is what appears in the DT_NEEDED entries of images linked against it.", aka=["DT_SONAME", "shared object name"], see=["dt-needed", "install-name"], concept="shared-libraries", match=["DT_SONAME", "SONAME"]),
    T("dt-needed", "DT_NEEDED", "An entry of the ELF dynamic section naming a library that must be loaded.", aka=["needed library"], see=["dynamic-section", "soname"], concept="shared-libraries", match=["DT_NEEDED"]),
    T("rpath", "run path", "A list of directories stored in an image and searched for its libraries: LC_RPATH in Mach-O (used to expand @rpath), DT_RUNPATH or DT_RPATH in ELF.", aka=["rpath", "runpath", "LC_RPATH", "DT_RUNPATH", "DT_RPATH", "$ORIGIN"], see=["install-name", "dt-needed"], concept="shared-libraries", match=["LC_RPATH", "DT_RUNPATH", "DT_RPATH", "run path", "run paths"]),
    T("dynamic-section", "dynamic section", "The ELF .dynamic table of (tag, value) pairs from which the dynamic linker finds everything else: needed libraries, symbol and string tables, relocations, initialisers, flags.", aka=[".dynamic", "DT_", "Elf64_Dyn"], see=["pt-dynamic", "dt-needed", "dynsym"], concept="elf-dynamic", match=[".dynamic"]),
    T("got", "GOT", "Global offset table: a table of pointers in a data segment, filled in by the dynamic linker, through which code reaches symbols in other images.", aka=["global offset table", ".got", ".got.plt", "__got", "__auth_got", "non-lazy pointers"], see=["plt", "stub", "iat", "relro"], concept="got-plt", match=["GOT", ".got", ".got.plt", "__got", "__auth_got"]),
    T("plt", "PLT", "Procedure linkage table: in ELF, the short code sequences that jump through GOT slots to imported functions.", aka=["procedure linkage table", ".plt", ".plt.sec", ".plt.got"], see=["got", "stub", "lazy-binding"], concept="got-plt", match=["PLT", ".plt", ".plt.sec"]),
    T("stub", "stub", "In Mach-O, a short code sequence in __TEXT,__stubs that loads a pointer from the GOT and jumps to it. The counterpart of an ELF PLT entry.", aka=["__stubs", "__auth_stubs", "symbol stub", "S_SYMBOL_STUBS", "__stub_helper", "import thunk", "thunk"], see=["got", "plt", "indirect-symbol-table"], concept="got-plt", match=["__stubs", "__auth_stubs", "__stub_helper", "thunk", "thunks"]),
    T("iat", "IAT", "Import address table: in PE, the array of pointers, one per imported function, that the loader fills in and that code calls through.", aka=["import address table", "FirstThunk", "__imp_"], see=["import-directory", "ilt", "got"], concept="pe-imports", match=["IAT", "DATA_DIR_IAT"]),
    T("ilt", "import lookup table", "In PE, the array that describes what to import (by name or ordinal) for each IAT slot. Also called the import name table (INT).", aka=["ILT", "INT", "import name table", "OriginalFirstThunk"], see=["iat", "import-directory"], concept="pe-imports", match=["ILT"]),
    T("import-directory", "import directory", "The PE table (data directory 1) with one IMAGE_IMPORT_DESCRIPTOR per imported DLL, each pointing at the DLL's name, its lookup table and its IAT.", aka=["import table", "IMAGE_IMPORT_DESCRIPTOR", ".idata"], see=["iat", "ilt", "data-directory"], concept="pe-imports", match=["DATA_DIR_IMPORT_TABLE", "IMAGE_IMPORT_DESCRIPTOR"]),
    T("lazy-binding", "lazy binding", "Resolving an imported function on its first call instead of at load time.", aka=["lazy bind", "__la_symbol_ptr", "dyld_stub_binder", "delay-load"], see=["bind", "bind-now", "plt"], concept="lazy-binding", match=["__la_symbol_ptr"]),
    T("bind-now", "bind now", "Resolving every import at load time. On ELF it is requested with -z now and recorded as DF_BIND_NOW or DF_1_NOW; together with PT_GNU_RELRO it gives full RELRO.", aka=["BIND_NOW", "DF_BIND_NOW", "DF_1_NOW", "eager binding"], see=["lazy-binding", "relro"], concept="lazy-binding", match=["BIND_NOW", "DF_BIND_NOW", "DF_1_NOW"]),
    T("symbol-versioning", "symbol versioning", "A GNU extension that attaches a version to each dynamic symbol (puts@GLIBC_2.2.5) so that a library can provide several versions of a function.", aka=[".gnu.version", "GLIBC_"], see=["dynsym"], concept="elf-dynamic"),
    T("gnu-hash", "GNU hash table", "The hash table (.gnu.hash, DT_GNU_HASH) the ELF dynamic linker uses to look symbols up by name quickly.", aka=[".gnu.hash", "DT_GNU_HASH", ".hash"], see=["dynsym"], concept="elf-dynamic", match=[".gnu.hash"]),
    T("ntdll", "ntdll.dll", "The lowest-level user-mode Windows library. It is mapped into every process and contains the loader and the system call stubs.", aka=["LdrInitializeThunk", "Windows loader"], see=["dynamic-linker", "peb", "syscall"], concept="process-startup-windows"),

    # ---- process start
    T("process", "process", "A running program: an address space, one or more threads, and the resources the kernel tracks for them.", see=["address-space", "execve"], concept="process-startup-linux"),
    T("kernel", "kernel", "The privileged core of the operating system: XNU on macOS, Linux, the Windows NT kernel. It creates processes and maps files into them.", aka=["XNU"], see=["syscall", "loader"], concept="process-startup-linux"),
    T("execve", "execve", "The UNIX system call that replaces the calling process's program with a new one.", aka=["exec", "posix_spawn", "CreateProcess"], see=["process", "kernel"], concept="process-startup-linux"),
    T("entry-point", "entry point", "The address where execution of an image begins: e_entry in ELF, LC_MAIN's entryoff in Mach-O, AddressOfEntryPoint in PE. In ELF and PE it is start-up code, not main; LC_MAIN names main itself, which dyld calls.", aka=["e_entry", "AddressOfEntryPoint", "LC_MAIN", "entryoff", "_start", "OEP"], see=["crt", "lc-unixthread"], concept="process-startup-linux", match=["Entry point", "entry point", "LC_MAIN", "AddressOfEntryPoint"]),
    T("lc-unixthread", "LC_UNIXTHREAD", "The Mach-O load command that gives a complete initial register state, including the program counter. Used by statically linked files such as the kernel, dyld and firmware; LC_MAIN replaced it for ordinary executables.", aka=["thread state", "LC_THREAD"], see=["entry-point"], concept="process-startup-macos", match=["LC_UNIXTHREAD"]),
    T("crt", "C runtime start-up", "The code that runs before main: it sets up the C library, runs initialisers and calls main. On ELF systems and Windows a small part is linked into every program and is its entry point; on macOS dyld and libSystem do this work and call main directly.", aka=["crt0", "crt1.o", "_start", "mainCRTStartup", "__libc_start_main"], see=["entry-point", "initializer"], concept="process-startup-linux"),
    T("auxiliary-vector", "auxiliary vector", "A list of (type, value) pairs the Linux kernel places on the initial stack to tell the dynamic linker where the program headers and entry point are, the page size, and more.", aka=["auxv", "AT_ENTRY", "AT_PHDR", "AT_RANDOM"], see=["interpreter"], concept="process-startup-linux"),
    T("peb", "PEB", "Process Environment Block: the Windows user-mode structure that records the image base, the loaded modules, the command line and other per-process data. Each thread has a TEB.", aka=["Process Environment Block", "TEB"], see=["ntdll"], concept="process-startup-windows", match=["PEB"]),
    T("initializer", "initialiser", "A function called automatically before main: a C++ static constructor or a function marked as a constructor. Listed in __mod_init_func, .init_array or the CRT's tables.", aka=["constructor", ".init_array", "__mod_init_func", "__init_offsets", "DT_INIT_ARRAY", "static initializer"], see=["crt", "tls-callback"], concept="initializers-tls", match=[".init_array", "__mod_init_func", "__init_offsets"]),
    T("tls", "thread-local storage", "Variables of which each thread has its own copy. The file holds a template of initial values: PT_TLS in ELF, the TLS directory in PE, __thread_data and __thread_bss (with descriptors in __thread_vars) in Mach-O.", aka=["TLS", "PT_TLS", "__thread_vars", ".tdata", ".tbss", "thread_local"], see=["tls-callback"], concept="initializers-tls", match=["TLS", "PT_TLS", "__thread_vars", "__thread_data"]),
    T("tls-callback", "TLS callback", "A function listed in a PE file's TLS directory. The loader calls it at process and thread start and exit; for the executable the first call comes before the entry point.", aka=["AddressOfCallBacks", "IMAGE_TLS_DIRECTORY"], see=["tls", "entry-point"], concept="initializers-tls", match=["DATA_DIR_TLS_TABLE", "TLS callback", "TLS callbacks"]),
    T("subsystem", "subsystem", "The PE optional header field that states the environment an image needs: Windows GUI, console, native (drivers), EFI.", aka=["IMAGE_SUBSYSTEM_WINDOWS_CUI", "IMAGE_SUBSYSTEM_WINDOWS_GUI"], see=["optional-header"], concept="process-startup-windows", match=["Subsystem"]),

    # ---- position independence and ASLR
    T("pic", "position-independent code", "Code that runs correctly at any address because it refers to its own code and data relative to the current instruction.", aka=["PIC", "-fPIC"], see=["pie", "rip-relative", "got"], concept="pic-pie", match=["PIC"]),
    T("pie", "PIE", "Position-independent executable: a main program that can be loaded at any address. MH_PIE in Mach-O, type ET_DYN in ELF, DYNAMIC_BASE with relocations in PE.", aka=["position-independent executable", "MH_PIE", "ET_DYN", "DF_1_PIE"], see=["pic", "aslr"], concept="pic-pie", match=["PIE", "MH_PIE", "ET_DYN", "DF_1_PIE"]),
    T("aslr", "ASLR", "Address space layout randomisation: loading images, stacks and heaps at addresses that differ between runs.", aka=["address space layout randomization", "DYNAMIC_BASE", "HIGH_ENTROPY_VA"], see=["pie", "slide", "mitigation"], concept="aslr", match=["ASLR", "DYNAMIC_BASE", "HIGH_ENTROPY_VA", "IMAGE_DLLCHARACTERISTICS_DYNAMIC_BASE", "IMAGE_DLLCHARACTERISTICS_HIGH_ENTROPY_VA"]),
    T("rip-relative", "RIP-relative addressing", "The x86-64 addressing mode that locates data at a fixed distance from the address of the next instruction. The basis of position-independent code on that CPU.", aka=["PC-relative", "[rip + disp]", "adrp"], see=["pic"], concept="pic-pie"),

    # ---- execution
    T("instruction", "instruction", "One operation of the CPU, encoded in 4 bytes on ARM64 and 1 to 15 bytes on x86-64.", see=["mnemonic", "operand", "disassembly"], concept="reading-disassembly"),
    T("mnemonic", "mnemonic", "The short name of an instruction's operation, such as mov, call or bl.", see=["instruction", "operand"], concept="reading-disassembly", match=["Mnemonic"]),
    T("operand", "operand", "What an instruction operates on: a register, a constant (immediate) or a memory location.", aka=["immediate"], see=["mnemonic", "register"], concept="reading-disassembly", match=["Operands"]),
    T("disassembly", "disassembly", "Machine code decoded back into instruction mnemonics and operands.", aka=["disassembler"], see=["instruction", "data-in-code"], concept="reading-disassembly"),
    T("register", "register", "A small, fast storage location inside the CPU. x86-64 has sixteen general ones (rax to r15); ARM64 has thirty-one (x0 to x30).", see=["stack-pointer", "frame-pointer", "link-register", "program-counter"], concept="reading-disassembly"),
    T("program-counter", "program counter", "The register that tracks where execution is: pc on ARM64 holds the address of the instruction being executed; rip on x86-64 holds the address of the next one.", aka=["instruction pointer", "rip", "pc", "eip"], see=["register"], concept="reading-disassembly"),
    T("stack-pointer", "stack pointer", "The register holding the address of the top of the stack: rsp on x86-64, sp on ARM64.", aka=["rsp", "sp", "esp"], see=["stack", "frame-pointer"], concept="stack-and-frames"),
    T("frame-pointer", "frame pointer", "A register that points at a fixed place in the current stack frame: rbp on x86-64, x29 on ARM64. Saved frame pointers link the frames into a chain.", aka=["rbp", "x29", "fp", "base pointer", "ebp"], see=["stack-frame", "prologue"], concept="stack-and-frames"),
    T("link-register", "link register", "On ARM64, register x30, which receives the return address when bl or blr is executed.", aka=["lr", "x30"], see=["return-address", "prologue"], concept="stack-and-frames"),
    T("return-address", "return address", "The address of the instruction after a call, where execution continues when the called function returns.", see=["stack-frame", "link-register", "rop"], concept="stack-and-frames"),
    T("stack-frame", "stack frame", "The part of the stack that belongs to one function call in progress: saved registers, return address, local variables.", aka=["frame", "activation record"], see=["stack", "prologue", "frame-pointer"], concept="stack-and-frames"),
    T("prologue", "prologue", "The instructions at the start of a function that save registers and set up its stack frame.", aka=["function prologue", "prolog"], see=["epilogue", "stack-frame"], concept="stack-and-frames"),
    T("epilogue", "epilogue", "The instructions at the end of a function that restore saved registers, remove the stack frame and return.", aka=["function epilogue", "epilog"], see=["prologue"], concept="stack-and-frames"),
    T("calling-convention", "calling convention", "The rules for passing arguments and results between functions and for which registers must be preserved.", aka=["cdecl", "stdcall", "System V AMD64 ABI", "AAPCS64", "fastcall"], see=["abi", "stack-frame"], concept="calling-conventions"),
    T("syscall", "system call", "A request from user code to the kernel, made with a dedicated instruction (syscall, svc, int 0x80) and a number selecting the service.", aka=["syscall", "svc", "supervisor call", "int 0x80"], see=["kernel", "vdso"], concept="syscalls"),
    T("vdso", "vDSO", "A small shared library that the Linux kernel maps into every process so that a few frequent system calls can be answered without entering the kernel.", aka=["virtual dynamic shared object", "linux-vdso.so.1"], see=["syscall"], concept="syscalls"),
    T("unwind-info", "unwind information", "Tables that describe how to restore the caller's registers from any point in a function. Used for exceptions and stack traces: .eh_frame, __unwind_info, .pdata.", aka=[".eh_frame", "__unwind_info", ".pdata", ".xdata", "exception directory", "__eh_frame"], see=["stack-frame", "debug-info"], concept="stack-and-frames", match=[".eh_frame", "__unwind_info", ".pdata", "__eh_frame"]),
    T("x86-64", "x86-64", "The 64-bit Intel/AMD architecture. Also called AMD64 and x64. Little-endian, variable-length instructions.", aka=["AMD64", "x64", "x86_64", "EM_X86_64", "IMAGE_FILE_MACHINE_AMD64", "CPU_TYPE_X86_64"], see=["arm64", "i386"], concept="reading-disassembly", match=["x86_64", "AMD64"]),
    T("i386", "i386", "The 32-bit Intel architecture, also written x86 or IA-32.", aka=["x86", "IA-32", "EM_386", "IMAGE_FILE_MACHINE_I386"], see=["x86-64"], concept="reading-disassembly", match=["i386"]),
    T("arm64", "ARM64", "The 64-bit ARM architecture, officially AArch64. Fixed 4-byte instructions.", aka=["AArch64", "EM_AARCH64", "IMAGE_FILE_MACHINE_ARM64", "CPU_TYPE_ARM64"], see=["arm64e", "x86-64"], concept="reading-disassembly", match=["arm64", "ARM64", "AArch64"]),
    T("arm64e", "arm64e", "Apple's ARM64 ABI variant that uses pointer authentication for return addresses and code pointers. A distinct CPU subtype in Mach-O.", aka=["CPU_SUBTYPE_ARM64E"], see=["pac", "arm64"], concept="cfi", match=["arm64e", "CPU_SUBTYPE_ARM64E"]),

    # ---- mitigations
    T("mitigation", "exploit mitigation", "A defence that does not remove a bug but blocks a step needed to exploit it.", aka=["hardening", "exploit mitigation"], see=["nx", "aslr", "stack-canary", "relro", "cfi"], concept="mitigations-overview", match=["Hardening"]),
    T("buffer-overflow", "buffer overflow", "Writing past the end of a buffer into whatever is next to it in memory.", aka=["stack overflow", "stack smashing", "memory corruption"], see=["stack-canary", "return-address"], concept="mitigations-overview"),
    T("rop", "return-oriented programming", "An attack that chains short existing code sequences ending in a return, by controlling the return addresses on the stack. A form of code reuse.", aka=["ROP", "code reuse", "ret2libc", "JOP"], see=["nx", "shadow-stack", "cfi"], concept="mitigations-overview"),
    T("nx", "NX", "No-execute: a per-page permission that stops data from being run as code. Called DEP on Windows and XN on ARM.", aka=["DEP", "data execution prevention", "XN", "NX_COMPAT", "non-executable stack"], see=["w-xor-x", "page-permissions", "pt-gnu-stack"], concept="nx-wx", match=["NX", "DEP", "NX_COMPAT", "IMAGE_DLLCHARACTERISTICS_NX_COMPAT"]),
    T("w-xor-x", "W^X", "The rule that a page is never writable and executable at the same time.", aka=["write xor execute", "RWX"], see=["nx", "jit"], concept="nx-wx", match=["W^X", "RWX"]),
    T("jit", "JIT", "Just-in-time compilation: generating machine code at run time. It needs memory that is written and then executed.", aka=["just-in-time", "MAP_JIT"], see=["w-xor-x", "entitlements"], concept="nx-wx", match=["JIT"]),
    T("stack-canary", "stack canary", "A secret value the compiler places between a function's local variables and its return address, checked before returning.", aka=["stack protector", "stack cookie", "/GS", "__stack_chk_guard", "__stack_chk_fail", "security cookie"], see=["buffer-overflow", "prologue"], concept="stack-canaries", match=["stack canary", "Stack canary", "__stack_chk_fail", "___stack_chk_fail", "___stack_chk_guard", "__stack_chk_guard"]),
    T("relro", "RELRO", "Relocation read-only: the ELF dynamic linker makes the GOT and related data read-only after relocating. Partial RELRO leaves the PLT's slots writable; full RELRO (with bind-now) covers them.", aka=["relocation read-only", "full RELRO", "partial RELRO"], see=["pt-gnu-relro", "bind-now", "data-const", "got"], concept="relro", match=["RELRO"]),
